    static func base(size: Int, kind: String, glyph: String, frame: Int) -> [UInt8] {
        let key = "\(size)/\(kind)/\(size == 11 ? "neutral" : glyph)/\(frame)"
        guard let encoded = encoded[key], let data = Data(base64Encoded: encoded) else {
            return [UInt8](repeating: 0, count: size * size * 3)
        }
        let runs = [UInt8](data)
        var out: [UInt8] = []; out.reserveCapacity(size * size * 3)
        for i in stride(from: 0, to: runs.count, by: 4) {
            for _ in 0..<Int(runs[i]) { out.append(contentsOf: runs[(i + 1)...(i + 3)]) }
        }
        return out
    }
